import {DEFAULTS, configFor, forecastURL, normalize, assessment, currentHour, windowsFor, direction} from './weather.mjs?v=19';
import {MESSAGES, localeFor} from './i18n.mjs?v=19';
const HOUR = 3600000;
const escapeHTML = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const CSS = new URL('./warun.css?v=22', import.meta.url).href;
// AI illustration based on the official APCO F1 MKII Azure #24 reference.
const GLIDER = `<img class="glider" src="data:image/png;base64," alt="" aria-hidden="true">`;
function fields(config, t) {
  return `<label class="wide">${t.language}<select name="language"><option value="pl" ${config.language==='pl'?'selected':''}>Polski</option><option value="en" ${config.language==='en'?'selected':''}>English</option></select></label>
    <label class="wide">${t.name}<input name="name" value="${escapeHTML(config.name)}" required maxlength="80"></label>
    ${[['latitude',-90,90,'any'],['longitude',-180,180,'any'],['wind_threshold',.5,30,.5],['precip_threshold',0,100,1],['forecast_hours',4,72,1]].map(([key,min,max,step])=>`<label>${t[key]}<input name="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${config[key]}" required></label>`).join('')}
    <label>${t.timezone}<input name="timezone" value="${escapeHTML(config.timezone)}" required></label>
    <label class="check wide"><input name="daylight_only" type="checkbox" ${config.daylight_only?'checked':''}>${t.daylight_only}</label>`;
}
function formConfig(form, previous) {
  const values = new FormData(form), next={...previous};
  for (const key of ['name','language','timezone']) next[key]=values.get(key);
  for (const key of ['latitude','longitude','wind_threshold','precip_threshold','forecast_hours']) next[key]=Number(values.get(key));
  next.daylight_only=values.has('daylight_only');
  return configFor(next);
}
class WarunCard extends HTMLElement {
  constructor() {
    super(); this.attachShadow({mode:'open'}); this.config={...DEFAULTS};
    this.data=null; this.loading=false; this.error=false;
    this.shadowRoot.addEventListener('click',event=>{if(event.target.closest('[data-refresh]')) this.refresh();});
    this.shadowRoot.addEventListener('submit',event=>{
      if(!event.target.matches('form')) return;
      event.preventDefault();
      try {this.setConfig(formConfig(event.target,this.config));}
      catch {this.shadowRoot.querySelector('[data-form-error]').textContent=this.t.invalid;}
    });
  }
  get t() {return MESSAGES[this.config.language];}
  fmt(value,digits=0) {return value==null||!Number.isFinite(value)?'—':Object.is(value,-0)?'0':value.toLocaleString(localeFor(this.config.language),{maximumFractionDigits:digits});}
  static getStubConfig() {return {...DEFAULTS};}
  static getConfigElement() {return document.createElement('apco-maniacs-editor');}
  set hass(value) {if(!this.inHA){this.inHA=true;if(this.isConnected)this.render();}}
  setConfig(input) {
    const next=configFor(input);
    if(JSON.stringify(next)===JSON.stringify(this.config)&&this.data)return;
    const sameSource=next.latitude===this.config.latitude&&next.longitude===this.config.longitude&&next.timezone===this.config.timezone;
    this.config=next; this.error=false;
    if(this.data&&sameSource){if(this.isConnected)this.render();return;}
    this.data=null;if(this.isConnected)this.refresh();
  }
  getCardSize(){return 8;}
  getGridOptions(){return {columns:12,min_columns:6};}
  connectedCallback(){
    this.render();this.refresh();this.timer=setInterval(()=>{
      if(!this.updated||Date.now()-this.updated>=15*60000)this.refresh();
      else if(!this.shadowRoot.querySelector('.settings[open]'))this.render();
    },60000);
  }
  disconnectedCallback(){clearInterval(this.timer);this.controller?.abort();}
  async refresh(){
    this.controller?.abort();const controller=new AbortController();this.controller=controller;
    const timeout=setTimeout(()=>controller.abort(),20000);this.loading=true;this.error=false;this.render();
    try{
      const response=await fetch(forecastURL(this.config),{signal:controller.signal});
      if(!response.ok)throw new Error(`HTTP ${response.status}`);
      const data=normalize(await response.json());
      if(controller!==this.controller||!this.isConnected)return;
      this.data=data;this.updated=Date.now();
    }catch(error){
      if(controller!==this.controller||!this.isConnected)return;
      this.error=true;console.warn('APCO Maniacs:',error.message);
    }finally{
      clearTimeout(timeout);if(controller===this.controller&&this.isConnected){this.loading=false;this.render();}
    }
  }
  time(value){return new Intl.DateTimeFormat(localeFor(this.config.language),{timeZone:this.config.timezone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(value);}
  day(value){const date=new Intl.DateTimeFormat(localeFor(this.config.language),{timeZone:this.config.timezone,weekday:'long',day:'numeric',month:'long'}).format(value);return date.charAt(0).toLocaleUpperCase(localeFor(this.config.language))+date.slice(1);}
  precipitation(value){return value===0?this.t.noRain:`${this.t.rain} ${this.fmt(value)}%`;}
  render(){
    const c=this.config,t=this.t,data=this.data,now=this.previewTime??Date.now();
    const hour=data?currentHour(data,now):null;
    const current=this.previewTime!=null?hour:data&&Number.isFinite(data.current.time)&&Math.abs(now-data.current.time)<HOUR?data.current:null;
    const status=!this.updated||Date.now()-this.updated>30*60000||this.error?'unknown':assessment(hour&&current?{...hour,wind:current.wind}:null,c);
    const windows=data?windowsFor(data,c,now):[],days=[...new Set(windows.map(w=>this.day(w.start)))];
    this.shadowRoot.innerHTML=`<link rel="stylesheet" href="${CSS}"><article class="card" lang="${c.language}" aria-label="APCO Maniacs: ${escapeHTML(c.name)}" aria-busy="${this.loading}">
      <header><div class="brand">${GLIDER}<div class="brand-copy"><div class="name-row"><h1 class="brand-name">${escapeHTML(c.name)}</h1><button type="button" class="refresh" data-refresh aria-label="${t.refreshLabel}" title="${t.refreshLabel}" ${this.loading?'disabled':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5M6.1 7a7 7 0 0 1 11.6-1L20 9M4 15l2.3 3A7 7 0 0 0 18 17"/></svg></button></div><span class="brand-subtitle">${t.subtitle}</span></div></div></header>
      ${this.error?`<div class="message" role="alert">${t.error} ${data?t.previous:''}</div>`:''}
      <section class="current alert ${status}" aria-label="${t.currentLabel}"><h2>${t.now} – ${this.time(now)}</h2>
      <p class="weather-line">${this.fmt(current?.temperature)}°C <span class="separator">|</span> ${t.wind} ${this.windHTML(current?.wind,current?.direction)} <span class="separator">|</span> ${this.precipitation(hour?.precip)}</p>
      ${status==='unknown'?`<p class="data-note">${this.loading&&!data?t.loading:t.currentMissing}</p>`:''}</section>
      ${data?`<section class="windows" aria-label="${t.forecast}">
      ${days.map(day=>`<h3${day===days[0]&&c.daylight_only&&day!==this.day(now)?` title="${escapeHTML(t.nextDay)}"`:''}>${escapeHTML(day)}</h3><div class="window-list">${windows.filter(w=>this.day(w.start)===day).map(w=>this.windowHTML(w)).join('')}</div>`).join('')}
      ${!windows.length?`<p class="empty">${t.empty}</p>`:''}</section>`:!this.loading?`<p class="empty">${t.noForecast}</p>`:`<div class="loading" role="status">${t.fetching}</div>`}
      <p class="limits">${t.wind} &lt; ${this.fmt(c.wind_threshold,1)} m/s | ${t.rain} &lt; ${this.fmt(c.precip_threshold)}%. ${t.limits}</p>
      ${!this.inHA?`<details class="settings"><summary>${t.settings}</summary><form>${fields(c,t)}<p class="wide hint">${t.temporary}</p><p class="wide form-error" data-form-error role="alert"></p><button class="save" type="submit">${t.apply}</button></form></details>`:''}
      <footer><span>${this.updated?`${t.updated} ${this.time(this.updated)} · ${t.interval}`:t.autoUpdate}</span><a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">${t.source}</a></footer></article>`;
  }
  windHTML(speed,bearing){
    const valid=typeof bearing==='number'&&Number.isFinite(bearing);
    return `<span class="wind-reading">${this.fmt(speed,1)} m/s <span class="wind-direction" title="${valid?`${this.t.windFrom} ${direction(bearing)}`:this.t.noDirection}">${valid?direction(bearing):'—'}</span></span>`;
  }
  windowHTML(w){
    const t=this.t;
    return `<section class="window alert ${w.status}" aria-label="${this.time(w.start)} – ${this.time(w.end)}: ${t[w.status]}"><h4>${this.time(w.start)} – ${this.time(w.end)}</h4>
    <p class="weather-line">${this.fmt(w.min)}…${this.fmt(w.max)}°C <span class="separator">|</span> ${t.windMax} ${this.windHTML(w.wind,w.direction)} <span class="separator">|</span> ${this.precipitation(w.precip)}</p>
    ${w.status==='unknown'?`<p class="data-note">${t.incomplete}</p>`:''}</section>`;
  }
}
class APCOEditor extends HTMLElement {
  constructor(){
    super();this.attachShadow({mode:'open'});
    this.shadowRoot.addEventListener('change',event=>{
      const form=event.target.closest('form');if(!form||!form.reportValidity())return;
      try{
        this.config=formConfig(form,this.config);this.render();
        this.dispatchEvent(new CustomEvent('config-changed',{detail:{config:this.config},bubbles:true,composed:true}));
      }catch{this.shadowRoot.querySelector('[data-form-error]').textContent=MESSAGES[this.config.language].invalid;}
    });
    this.shadowRoot.addEventListener('submit',event=>event.preventDefault());
  }
  setConfig(config){this.config=configFor(config);this.render();}
  render(){if(!this.config)return;const t=MESSAGES[this.config.language];this.shadowRoot.innerHTML=`<link rel="stylesheet" href="${CSS}"><div class="card editor" lang="${this.config.language}"><h2>APCO Maniacs</h2><form>${fields(this.config,t)}<p class="wide form-error" data-form-error role="alert"></p></form></div>`;}
}
if(!customElements.get('warun-card'))customElements.define('warun-card',WarunCard);
if(!customElements.get('apco-maniacs-card'))customElements.define('apco-maniacs-card',class extends WarunCard{});
if(!customElements.get('apco-maniacs-editor'))customElements.define('apco-maniacs-editor',APCOEditor);
window.customCards=window.customCards||[];
if(!window.customCards.some(card=>card.type==='apco-maniacs-card'))window.customCards.push({type:'apco-maniacs-card',name:'APCO Maniacs',description:MESSAGES.pl.description});
